const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const message = data.message || {};

const phone = (data.key?.remoteJid || body.remoteJid || '').replace('@s.whatsapp.net', '').replace('@c.us', '');
const pushName = data.pushName || body.pushName || 'Cliente';
const messageId = data.key?.id || body.messageId || '';

// Detecta tipo de mensagem
const isAudio = !!(message.audioMessage || message.pttMessage);
const isImage = !!(message.imageMessage);
const isDocument = !!(message.documentMessage);
const isMedia = isImage || isDocument;

// Captura base64 e mimetype de imagem/documento
// ⚠️ Na Evolution API, o base64 da imagem vem em message.base64 (raiz do message)
const mediaBase64 = (isImage || isDocument) ? (message.base64 || data.base64 || body.base64 || '') : '';
const mediaMimeType = message.imageMessage?.mimetype ||
                     message.documentMessage?.mimetype || 'image/jpeg';
const mediaCaption = message.imageMessage?.caption ||
                     message.documentMessage?.caption || '';
const mediaFileName = message.documentMessage?.fileName || '';

// Captura base64 de áudio
// Só captura base64 de áudio se for mensagem de áudio
const audioBase64 = isAudio ? (message.base64 || data.base64 || body.base64 || message.audioMessage?.base64 || '') : '';
const audioUrl = message.audioMessage?.url || message.pttMessage?.url || '';

const text = message.conversation || message.extendedTextMessage?.text || body.text || '';

if (!phone || phone.includes('-')) {
  throw new Error('Mensagem ignorada: vazia ou de grupo');
}

return [{
  json: {
    phone,
    text,
    messageId,
    pushName,
    isAudio,
    isImage,
    isDocument,
    isMedia,
    audioUrl,
    audioBase64,
    mediaBase64,
    mediaMimeType,
    mediaCaption,
    mediaFileName
  }
}];

const whisperData = $input.first().json;
const dadosOriginais = $('Extrair Dados da Mensagem').item.json;
const textoTranscrito = whisperData?.text || whisperData?.transcription || '';
return [{
  json: {
    phone: dadosOriginais.phone,
    pushName: dadosOriginais.pushName,
    text: textoTranscrito,
    messageId: dadosOriginais.messageId,
    isAudio: true
  }
}];

const dados = $input.first().json;
const mediaBase64 = dados.mediaBase64 || '';
const mediaMimeType = dados.mediaMimeType || 'image/jpeg';
const mediaCaption = dados.mediaCaption || '';
const mediaFileName = dados.mediaFileName || '';
const isDocument = dados.isDocument;

const isPDF = isDocument && (mediaMimeType === 'application/pdf' || (mediaFileName || '').toLowerCase().endsWith('.pdf'));

let userContent;
if (isPDF) {
  userContent = [
    { type: 'file', file: { filename: mediaFileName || 'doc.pdf', file_data: `data:application/pdf;base64,${mediaBase64}` } },
    { type: 'text', text: mediaCaption ? `Cliente enviou arquivo com mensagem: "${mediaCaption}". Analise e descreva o que vê relacionado ao veículo ou câmbio.` : 'Analise este documento e descreva o que vê relacionado ao veículo ou câmbio automático.' }
  ];
} else {
  userContent = [
    { type: 'image_url', image_url: { url: `data:${mediaMimeType};base64,${mediaBase64}`, detail: 'high' } },
    { type: 'text', text: mediaCaption ? `Cliente enviou imagem com mensagem: "${mediaCaption}". Descreva o que vê relacionado ao veículo ou câmbio automático.` : 'Analise esta imagem de veículo/câmbio e descreva o que vê (problema visível, componente, luz de aviso no painel, vazamento, etc.).' }
  ];
}

const messages = [
  {
    role: 'system',
    content: 'Você é um técnico especialista em câmbio automático analisando imagens. Descreva tecnicamente o que está visível: luzes de aviso no painel, componentes de câmbio, vazamentos, sinais de desgaste. Seja específico e objetivo. Responda em português.'
  },
  { role: 'user', content: userContent }
];

return [{ json: { ...dados, visionBodyStr: JSON.stringify({ model: 'gpt-4o', max_tokens: 500, messages }) } }];

const visionData = $input.first().json;
const dadosOriginais = $('Extrair Dados da Mensagem').item.json;
const rawContent = visionData?.choices?.[0]?.message?.content || '';

const textoEnriquecido = `[CLIENTE ENVIOU ${dadosOriginais.isDocument ? 'ARQUIVO' : 'IMAGEM'}]\nAnálise técnica: ${rawContent}${dadosOriginais.mediaCaption ? `\nMensagem junto à imagem: "${dadosOriginais.mediaCaption}"` : ''}`;

return [{
  json: {
    phone: dadosOriginais.phone,
    pushName: dadosOriginais.pushName,
    text: textoEnriquecido,
    messageId: dadosOriginais.messageId,
    isAudio: false,
    isImage: dadosOriginais.isImage,
    isDocument: dadosOriginais.isDocument,
    isMedia: true
  }
}];

let dadosFinal;
try {
  dadosFinal = $('Unificar Análise Vision').item.json;
  if (dadosFinal) return [{ json: dadosFinal }];
} catch(e) {}
try {
  dadosFinal = $('Unificar Transcrição').item.json;
  if (dadosFinal) return [{ json: dadosFinal }];
} catch(e) {}
dadosFinal = $('Extrair Dados da Mensagem').item.json;
return [{ json: dadosFinal }];

const extrair = $('Merge Texto+Audio').item.json;
let clienteData;
try {
  const novoResp = $('Cadastrar Novo Cliente').item.json;
  const arr = Array.isArray(novoResp) ? novoResp : [novoResp];
  if (arr.length > 0 && arr[0].id) clienteData = arr[0];
} catch(e) {}
if (!clienteData) {
  const existenteResp = $('Buscar Cliente').item.json;
  const arr = Array.isArray(existenteResp) ? existenteResp : [existenteResp];
  clienteData = arr.length > 0 ? arr[0] : {};
}
return [{
  json: {
    phone: extrair.phone,
    pushName: extrair.pushName,
    userMessage: extrair.text,
    isAudio: extrair.isAudio || false,
    isMedia: extrair.isMedia || false,
    clienteId: clienteData?.id,
    nomeCliente: clienteData?.nome || extrair.pushName,
    stage: clienteData?.stage || 'BOAS_VINDAS'
  }
}];

const cliente = $('Unificar Dados do Cliente').item.json;
const rawInput = $input.all();
let historico = [];
if (rawInput.length === 1 && Array.isArray(rawInput[0].json)) {
  historico = rawInput[0].json;
} else {
  historico = rawInput.map(i => i.json).filter(i => i && i.role);
}

const stage = cliente.stage;
const nomeCliente = cliente.nomeCliente || cliente.pushName || 'você';

const prompts = {
  BOAS_VINDAS: `Você é Camila da Jairo Mec — especialista em câmbio automático em Belo Horizonte 🔧⚙️

INFORMAÇÕES DA EMPRESA:
- Especialidade: Câmbio Automático (todas as marcas e modelos)
- Instagram: @jairomecbh
- Endereço: Av. Flor de Seda, 969 - Lindéia, Belo Horizonte/MG
- Horário: Segunda a Sexta das 8h às 18h
- Atendemos APENAS Belo Horizonte e região

SERVIÇOS:
- Diagnóstico eletrônico de câmbio automático
- Revisão e manutenção preventiva
- Reconstrução completa de câmbio
- Reparo de mecatrônica e corpo de válvulas
- Troca de óleo ATF (máquina flush)
- Câmbio CVT, DSG, PDK e DCT
- Câmbio para importados premium

PERSONALIDADE:
- Seja simpática, calorosa e profissional
- Use o nome do cliente: ${nomeCliente}
- Use emojis com moderação

INSTRUÇÃO:
Apresente-se como Camila da Jairo Mec, especialistas em câmbio automático em BH, e pergunte em que pode ajudar.
Se o cliente perguntar sobre orçamento ou mencionar problema: [MOVER_PARA_ATENDIMENTO]

REGRAS:
- Responda APENAS sobre câmbio automático
- NUNCA mencione que é virtual ou IA
- NUNCA mencione o número de telefone proativamente
- Se o cliente quiser agendar: "Vou agendar aqui pra você, ${nomeCliente}! 😊 Pode trazer ainda hoje (até as 18h, de segunda a sexta) ou amanhã. A Camila já deixou aqui avisado!"`,

  ATENDIMENTO: `Você é Camila da Jairo Mec — especialista em câmbio automático em Belo Horizonte 🔧⚙️

INFORMAÇÕES DA EMPRESA:
- Especialidade: Câmbio Automático (todas as marcas e modelos)
- Instagram: @jairomecbh
- Endereço: Av. Flor de Seda, 969 - Lindéia, Belo Horizonte/MG
- Horário: Segunda a Sexta das 8h às 18h
- Atendemos APENAS Belo Horizonte e região

⚠️ REGRAS ABSOLUTAS:

1. ORÇAMENTOS: NUNCA forneça valores ou estimativas de preço por mensagem.
   Diga sempre: "Para um orçamento preciso precisamos avaliar o câmbio do seu carro pessoalmente. Pode trazer de segunda a sexta, das 8h às 18h, que fazemos o orçamento na hora, sem compromisso! 📍 Av. Flor de Seda, 969 - Lindéia, BH 😊"

2. CARRO NA OFICINA: Se o cliente perguntar sobre o status do carro já na oficina:
   - Peça a placa: "Pode me informar a placa do veículo?"
   - Após receber a placa, diga: "Anotei a placa! Vou passar para nossa equipe e entraremos em contato pelo WhatsApp o mais breve possível com uma atualização. ✅"

3. FORA DE BH: Diga gentilmente: "No momento atendemos apenas em Belo Horizonte e região. Mas qualquer dúvida técnica sobre câmbio pode perguntar! 😊"

4. DÚVIDAS TÉCNICAS: Você PODE e DEVE responder sobre câmbio automático. Sempre termine direcionando para a oficina.

5. FOCO: Responda APENAS sobre câmbio automático. Se o cliente perguntar sobre outros assuntos, diga: "Aqui sou especialista em câmbio automático. Posso te ajudar com alguma dúvida sobre câmbio? 😊"

6. TELEFONE: Mencione o número (31) 8289-0190 SOMENTE se: o cliente já deixou o carro na oficina, está muito nervoso/irritado, ou é cliente já conhecido. NUNCA mencione proativamente em outros casos.

7. AGENDAMENTO: Quando o cliente demonstrar interesse em trazer o carro ou quiser agendar, diga SEMPRE exatamente isso: "Vou agendar aqui pra você, ${nomeCliente}! 😊 Pode trazer ainda hoje (até as 18h, de segunda a sexta) ou amanhã. Quando você trazer o carro é importante que você diga que eu agendei pra você, diga que a Camila já agendou pra você e deixou avisado ok!"

CONHECIMENTO TÉCNICO:
- Sintomas: solavanco/tranco nas trocas, patinação (motor acelera mas carro não avança), dificuldade de engate, ruídos ao trocar marcha, luz de câmbio no painel, trava em modo emergência
- Manutenção: troca de óleo ATF a cada 40.000-60.000 km (varia por marca/modelo)
- CVT: correia/corrente metálica; Honda, Toyota, Nissan, Subaru; sintomas: vibração, chiado, patinação
- DSG/DCT (VW, BMW, Ford): solavanco em baixa velocidade, especialmente nos primeiros km
- PDK (Porsche): similar DSG, alta precisão, requer cuidado especial
- Mecatrônica: quando falha trava em modo emergência ou gera código de falha
- Marcas atendidas: VW, Chevrolet, Ford, Fiat, Toyota, Honda, Hyundai, BMW, Mercedes, Audi, Land Rover, Kia, Renault, Nissan, Jeep, Mitsubishi, Peugeot, Citroën e mais

PERSONALIDADE:
- Nome do cliente: ${nomeCliente}
- Simpática, calorosa, demonstre expertise
- Sempre termine direcionando para a oficina
- Use emojis com moderação`
};

const systemPrompt = prompts[stage] || prompts['BOAS_VINDAS'];

const historicoFormatado = historico.length > 0
  ? '\n\n=== HISTÓRICO DA CONVERSA ===\n' +
    historico.filter(m => m && m.role).map(m => {
      const role = m.role === 'assistant' ? 'Camila' : 'Cliente';
      return `${role}: ${m.conteudo || m.content || ''}`;
    }).join('\n') +
    '\n=== FIM DO HISTÓRICO ==='
  : '';

let novoStage = stage;
if (stage === 'BOAS_VINDAS') novoStage = 'ATENDIMENTO';

return [{
  json: {
    phone: cliente.phone,
    clienteId: cliente.clienteId,
    nomeCliente,
    userMessage: cliente.userMessage,
    stage,
    novoStage,
    systemPrompt: systemPrompt + historicoFormatado,
    mensagensCompletas: [{ role: 'user', content: cliente.userMessage || 'Olá' }]
  }
}];

const dadosPrompt = $('Montar Prompt por Stage').item.json;
const gptData = $input.first().json;

let respostaGPT = gptData?.message?.content
  || gptData?.choices?.[0]?.message?.content
  || 'Olá! Sou a Camila da Jairo Mec 😊 Como posso ajudar com seu câmbio?';

respostaGPT = respostaGPT.replace(/\[MOVER_PARA_ATENDIMENTO\]/gi, '').trim();

const respostaOriginal = gptData?.message?.content || '';
let novoStage = dadosPrompt.novoStage;

if (dadosPrompt.stage === 'BOAS_VINDAS' && respostaOriginal.includes('[MOVER_PARA_ATENDIMENTO]')) {
  novoStage = 'ATENDIMENTO';
}

return [{
  json: {
    phone: dadosPrompt.phone,
    clienteId: dadosPrompt.clienteId,
    userMessage: dadosPrompt.userMessage,
    respostaGPT,
    novoStage,
    stage: dadosPrompt.stage
  }
}];

const resp = $('Extrair Resposta GPT').item.json;
const payload = [
  { cliente_id: resp.clienteId, role: 'user',      conteudo: resp.userMessage  || '' },
  { cliente_id: resp.clienteId, role: 'assistant', conteudo: resp.respostaGPT || '' }
];
return [{
  json: {
    bodyStr: JSON.stringify(payload),
    phone:        resp.phone,
    clienteId:    resp.clienteId,
    userMessage:  resp.userMessage,
    respostaGPT:  resp.respostaGPT,
    novoStage:    resp.novoStage,
    stage:        resp.stage
  }
}];
